// Internal child process. The parent supplies only SVG generated by drawing-axi.
import { readFileSync } from 'node:fs';
import { Resvg } from '@resvg/resvg-js';

const svg = readFileSync(0);
const renderer = new Resvg(svg, {
  background: '#ffffff',
  font: { loadSystemFonts: process.argv[2] === 'text' },
  logLevel: 'off',
});
process.stdout.write(renderer.render().asPng());
